using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Imaging;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Net;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
namespace NightLens {
internal sealed class SurveyPicture:IDisposable {public Bitmap Image;public string Survey;public SurveyPicture(Bitmap image,string survey){Image=image;Survey=survey;}public void Dispose(){Image?.Dispose();}}
internal static class SurveyImages {
    static readonly SemaphoreSlim network=new SemaphoreSlim(6);public static string TileRoot {get{return Path.Combine(ObjectImages.CacheFolder,"SurveyTiles");}}
    const int Side=900,TileSize=512;const double R=Math.PI/180;
    internal static byte[] FetchBytes(string url,DateTime deadline,int maximum=4*1024*1024){int left=(int)(deadline-DateTime.UtcNow).TotalMilliseconds;if(left<100)throw new TimeoutException("Image time budget expired.");int timeout=Math.Min(7000,left);if(!network.Wait(timeout))throw new TimeoutException("Image queue is busy.");try{var request=(HttpWebRequest)WebRequest.Create(url);request.UserAgent="NightLens color reference / 8.2";request.Timeout=timeout;request.ReadWriteTimeout=timeout;request.ServicePoint.ConnectionLimit=6;using(var abort=new System.Threading.Timer(x=>request.Abort(),null,timeout,Timeout.Infinite))using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=new MemoryStream()){byte[] buffer=new byte[32768];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(output.Length+n>maximum||DateTime.UtcNow>deadline)throw new IOException("Image response exceeds its size or time limit.");output.Write(buffer,0,n);}return output.ToArray();}}finally{network.Release();}}
    static Bitmap Decode(byte[] bytes){using(var stream=new MemoryStream(bytes))using(var image=Image.FromStream(stream,false,true)){if(image.Width<128||image.Height<128||image.Width>4096||image.Height>4096)throw new InvalidDataException("Unexpected survey image size.");return new Bitmap(image);}}
    internal static SurveyPicture Fetch(Target target){var ps=TryPanStarrs(target,DateTime.UtcNow.AddSeconds(13));if(ps!=null)return ps;return Dss(target,DateTime.UtcNow.AddSeconds(22));}
    static SurveyPicture TryPanStarrs(Target t,DateTime deadline){if(t.Dec< -29.5||ObjectImages.Field(t)>25)return null;try{string coordinates="ra="+(t.Ra*15).ToString("0.000000",CultureInfo.InvariantCulture)+"&dec="+t.Dec.ToString("0.000000",CultureInfo.InvariantCulture);string table=Encoding.UTF8.GetString(FetchBytes("https://ps1images.stsci.edu/cgi-bin/ps1filenames.py?"+coordinates+"&filters=gri&type=stack&format=csv",deadline,256*1024));var lines=table.Split('\n').Where(s=>!string.IsNullOrWhiteSpace(s)).ToArray();if(lines.Length<4)return null;var header=Regex.Split(lines[0].Trim(),@"[\s,]+");int filter=Array.IndexOf(header,"filter"),file=Array.IndexOf(header,"filename"),bad=Array.IndexOf(header,"badflag");if(filter<0||file<0)return null;var bands=new Dictionary<string,string>();foreach(string line in lines.Skip(1)){var row=Regex.Split(line.Trim(),@"[\s,]+");if(row.Length<header.Length||bad>=0&&row[bad]!="0"||!Regex.IsMatch(row[file],@"^/[A-Za-z0-9_./-]+\.fits$")||row[file].Contains(".."))continue;if(!bands.ContainsKey(row[filter]))bands[row[filter]]=row[file];}if(!new[]{"g","r","i"}.All(b=>bands.ContainsKey(b)))return null;int pixels=(int)Math.Ceiling(ObjectImages.Field(t)*240);string url="https://ps1images.stsci.edu/cgi-bin/fitscut.cgi?"+coordinates+"&size="+pixels+"&output_size=1000&format=jpg&red="+Uri.EscapeDataString(bands["i"])+"&green="+Uri.EscapeDataString(bands["r"])+"&blue="+Uri.EscapeDataString(bands["g"]);var image=Decode(FetchBytes(url,deadline));if(!HasData(image)){image.Dispose();return null;}return new SurveyPicture(image,"Pan-STARRS optical color (i/r/g)");}catch{return null;}}
    static bool HasData(Bitmap image){int count=0,max=0;for(int y=8;y<image.Height;y+=Math.Max(1,image.Height/40))for(int x=8;x<image.Width;x+=Math.Max(1,image.Width/40)){var c=image.GetPixel(x,y);int value=c.R+c.G+c.B;max=Math.Max(max,value);if(value>12)count++;}return count>20&&max>45;}
    static ulong Spread(uint value){ulong x=value;x=(x|(x<<16))&0x0000FFFF0000FFFFUL;x=(x|(x<<8))&0x00FF00FF00FF00FFUL;x=(x|(x<<4))&0x0F0F0F0F0F0F0F0FUL;x=(x|(x<<2))&0x3333333333333333UL;return (x|(x<<1))&0x5555555555555555UL;}
    static int Compact(ulong x){x&=0x5555555555555555UL;x=(x|(x>>1))&0x3333333333333333UL;x=(x|(x>>2))&0x0F0F0F0F0F0F0F0FUL;x=(x|(x>>4))&0x00FF00FF00FF00FFUL;x=(x|(x>>8))&0x0000FFFF0000FFFFUL;return (int)((x|(x>>16))&0xFFFFFFFFUL);}
    internal static ulong Nested(double ra,double dec,int order){int n=1<<order;double z=Math.Sin(dec*R),za=Math.Abs(z),tt=((ra%360+360)%360)/90;int face,ix,iy;if(za<=2.0/3){double a=n*(.5+tt),b=n*z*.75;int jp=(int)Math.Floor(a-b),jm=(int)Math.Floor(a+b),fp=jp/n,fm=jm/n;face=fp==fm?(fp|4):fp<fm?fp:fm+8;ix=jm&(n-1);iy=n-(jp&(n-1))-1;}else{int nt=Math.Min(3,(int)tt);double tp=tt-nt,tmp=n*Math.Sqrt(3*(1-za));int jp=Math.Min(n-1,(int)(tp*tmp)),jm=Math.Min(n-1,(int)((1-tp)*tmp));if(z>=0){face=nt;ix=n-jm-1;iy=n-jp-1;}else{face=nt+8;ix=jp;iy=jm;}}return (ulong)face*(ulong)n*(ulong)n+Spread((uint)ix)+(Spread((uint)iy)<<1);}
    internal static void TilePixel(ulong nested,out long tile,out int x,out int y){tile=(long)(nested>>18);x=Compact((nested&0x3FFFFUL)>>1);y=Compact(nested&0x3FFFFUL);}
    internal static ulong PixelAt(Target t,int x,int y,int side,int order,double field){double east=-(x+.5-side/2.0)*2*Math.Tan(field*R/2)/side,north=-(y+.5-side/2.0)*2*Math.Tan(field*R/2)/side,ra=t.Ra*15*R,dec=t.Dec*R;double vx=Math.Cos(dec)*Math.Cos(ra)-east*Math.Sin(ra)-north*Math.Sin(dec)*Math.Cos(ra),vy=Math.Cos(dec)*Math.Sin(ra)+east*Math.Cos(ra)-north*Math.Sin(dec)*Math.Sin(ra),vz=Math.Sin(dec)+north*Math.Cos(dec);return Nested(Math.Atan2(vy,vx)/R,Math.Atan2(vz,Math.Sqrt(vx*vx+vy*vy))/R,order+9);}
    sealed class Tile {public byte[] Pixels;public int Stride;}
    static Tile ReadTile(byte[] bytes){using(var image=Decode(bytes)){if(image.Width!=TileSize||image.Height!=TileSize||!HasData(image))return null;using(var rgb=new Bitmap(TileSize,TileSize,PixelFormat.Format24bppRgb)){using(var g=Graphics.FromImage(rgb))g.DrawImageUnscaled(image,0,0);var data=rgb.LockBits(new Rectangle(0,0,TileSize,TileSize),ImageLockMode.ReadOnly,PixelFormat.Format24bppRgb);try{var pixels=new byte[data.Stride*TileSize];Marshal.Copy(data.Scan0,pixels,0,pixels.Length);return new Tile{Pixels=pixels,Stride=data.Stride};}finally{rgb.UnlockBits(data);}}}}
    static Tile GetTile(int order,long tile,DateTime deadline){string folder=Path.Combine(TileRoot,"DSS2",order.ToString(CultureInfo.InvariantCulture)),file=Path.Combine(folder,tile+".jpg");try{if(File.Exists(file)){var hit=ReadTile(File.ReadAllBytes(file));if(hit!=null)return hit;}}catch{}
        foreach(string root in new[]{"https://casda.csiro.au/hips/DSS2/color","https://alasky.cds.unistra.fr/DSS/DSSColor","https://alaskybis.cds.unistra.fr/DSS/DSSColor"}){if(DateTime.UtcNow>=deadline)break;try{var bytes=FetchBytes(root+"/Norder"+order+"/Dir"+(tile/10000*10000)+"/Npix"+tile+".jpg",deadline,2*1024*1024);var result=ReadTile(bytes);if(result==null)continue;Directory.CreateDirectory(folder);string temporary=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllBytes(temporary,bytes);if(File.Exists(file))File.Replace(temporary,file,null);else File.Move(temporary,file);}finally{if(File.Exists(temporary))File.Delete(temporary);}return result;}catch{}}
        return null;
    }
    internal static SurveyPicture Dss(Target t,DateTime deadline){double field=ObjectImages.Field(t)/60;int order=Math.Max(3,Math.Min(9,(int)Math.Ceiling(Math.Log(58.6323/(512*field/Side),2))));var map=new ulong[Side*Side];var ids=new HashSet<long>();for(int y=0;y<Side;y++)for(int x=0;x<Side;x++){var p=PixelAt(t,x,y,Side,order,field);map[y*Side+x]=p;ids.Add((long)(p>>18));}if(ids.Count>64)throw new IOException("Survey field needs too many tiles.");var tiles=new ConcurrentDictionary<long,Tile>();Parallel.ForEach(ids,new ParallelOptions{MaxDegreeOfParallelism=6},id=>{var tile=GetTile(order,id,deadline);if(tile!=null)tiles[id]=tile;});
        long middle=(long)(map[(Side/2)*Side+Side/2]>>18);if(!tiles.ContainsKey(middle))throw new IOException("Color survey data is unavailable at this position. Click to retry.");
        var bitmap=new Bitmap(Side,Side,PixelFormat.Format24bppRgb);var data=bitmap.LockBits(new Rectangle(0,0,Side,Side),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);int missing=0;try{var output=new byte[data.Stride*Side];for(int y=0;y<Side;y++)for(int x=0;x<Side;x++){long id;int tx,ty;TilePixel(map[y*Side+x],out id,out tx,out ty);Tile tile;if(!tiles.TryGetValue(id,out tile)){missing++;continue;}int from=ty*tile.Stride+tx*3,to=y*data.Stride+x*3;output[to]=tile.Pixels[from];output[to+1]=tile.Pixels[from+1];output[to+2]=tile.Pixels[from+2];}Marshal.Copy(output,0,data.Scan0,output.Length);}finally{bitmap.UnlockBits(data);}if(missing>Side*Side*.1){bitmap.Dispose();throw new IOException("The survey field is incomplete. Click to retry.");}return new SurveyPicture(bitmap,"DSS2 optical color"+(missing>0?" · partial edge":""));
    }
}
}
